'use strict';
const fs = require('node:fs'), Module = require('node:module');
const file='/workspace/scratch/4f3d7636ef52/cristalwater/scripts/test-field-legacy-visit-drafts.js';
let source=fs.readFileSync(file,'utf8');
const needle="await prisma.serviceVisit.update({where:{id:visit.id},data:{notes:'Nota alterada pelo escritório',ph:7.8,alkalinity:100}});await page.evaluate(()=>loadRoute());";
if(!source.includes(needle))throw Error('Race insertion point changed');
source=source.replace(needle,`await page.waitForFunction(()=>!isSyncing);
  await prisma.serviceVisit.update({where:{id:visit.id},data:{notes:'Nota alterada pelo escritório',ph:7.8,alkalinity:100}});
  let raceRequests=0; const routePattern='**/visits/today?*';
  await page.route(routePattern,async route=>{raceRequests++;if(raceRequests===2)await new Promise(resolve=>setTimeout(resolve,750));await route.continue();});
  await page.evaluate(()=>{const previous=loadRoute();void loadRoute();return previous;});
  console.log('RACE previous load resolved while later route is delayed; conflicts='+await page.locator('#legacyDraftReview-'+visit.id+' > div').count());`);
source=source.replace("console.log('PASS unchanged fields", "await page.unroute(routePattern); console.log('PASS unchanged fields");
const markers=[],log=console.log;
const keep=setInterval(()=>{},1000),deadline=setTimeout(()=>{console.error('Draft race completion deadline');process.exit(1);},25000);
console.log=(...args)=>{const text=args.map(String).join(' ');if(text.startsWith('PASS ')){markers.push(text);if(markers.length===5){clearInterval(keep);clearTimeout(deadline);}}log(...args);};
process.on('exit',()=>{if(markers.length!==5)process.exitCode=1;});
const mod=new Module(file,module);mod.filename=file;mod.paths=Module._nodeModulePaths(require('node:path').dirname(file));mod._compile(source,file);
